<?php
require_once 'admin_auth.php';
require_once __DIR__ . '/../community/back-end/schema.php';
comunidade_instalar_schema($pdo);
$targets=['profile'=>['usuarios','id'],'post'=>['comunidade_publicacoes','id'],'video'=>['comunidade_videos','id'],'carousel'=>['comunidade_posts_visuais','id'],'reel'=>['comunidade_posts_visuais','id'],'story'=>['comunidade_stories','id'],'comment'=>['comunidade_comentarios_video','id'],'dm'=>['comunidade_mensagens_privadas','id'],'group_message'=>['comunidade_mensagens_grupo','id'],'group'=>['comunidade_grupos','id']];
if($_SERVER['REQUEST_METHOD']==='POST'){
    csrf_exigir();
    $type=(string)($_POST['content_type']??'');$id=(int)($_POST['content_id']??0);$status=(string)($_POST['status']??'');
    if(isset($targets[$type])&&$id>0&&in_array($status,['kept','hidden','removed'],true)){
        [$table,$key]=$targets[$type];
        if($type!=='profile'){$s=$pdo->prepare("UPDATE {$table} SET moderacao_status=? WHERE {$key}=?");$s->execute([$status==='kept'?'visible':$status,$id]);}
        $s=$pdo->prepare('UPDATE comunidade_denuncias SET status=?,revisado_por=?,revisado_em=NOW() WHERE conteudo_tipo=? AND conteudo_id=?');$s->execute([$status,$adminLogadoId,$type,$id]);
    }
    header('Location: moderacao.php?ok=1');exit;
}
$items=$pdo->query("SELECT d.id,d.conteudo_tipo AS content_type,d.conteudo_id AS content_id,d.motivo AS reason,d.detalhes AS details,d.status,d.criado_em AS created_at,u.nome AS reporter FROM comunidade_denuncias d JOIN usuarios u ON u.id=d.usuario_id WHERE d.status='pending' ORDER BY d.criado_em ASC,d.id ASC LIMIT 200")->fetchAll(PDO::FETCH_ASSOC);
$labels=['profile'=>'Perfil','post'=>'Publicação','video'=>'Vídeo','carousel'=>'Carrossel','reel'=>'Vídeo curto','story'=>'Story','comment'=>'Comentário','dm'=>'Mensagem privada','group_message'=>'Mensagem de grupo','group'=>'Grupo'];
?>
<!DOCTYPE html><html lang="pt-BR"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width, initial-scale=1.0"><title>Moderação | Admin AFDE</title><link rel="stylesheet" href="../css/admin.css"><link rel="stylesheet" href="../css/liquid-glass.css?v=101"><style>.moderation-card{background:#fff;border-radius:16px;padding:20px;margin:14px 0;box-shadow:0 8px 24px #17203312}.moderation-meta{display:flex;gap:12px;flex-wrap:wrap;color:#667085;font-size:13px}.moderation-card h3{margin:10px 0 6px}.moderation-details{background:#f8fafc;border-left:3px solid #78a9ff;padding:12px;margin:12px 0;white-space:pre-wrap}.moderation-actions{display:flex;gap:8px;flex-wrap:wrap}.moderation-actions button{border:0;border-radius:8px;padding:9px 13px;cursor:pointer;font-weight:700}.keep{background:#d1fae5;color:#065f46}.hide{background:#fef3c7;color:#92400e}.remove{background:#fee2e2;color:#991b1b}.empty-moderation{padding:40px;background:#fff;border-radius:16px;color:#667085}</style></head><body><?php $paginaAtual='moderacao'; include 'sidebar.php'; ?><main class="admin-content"><div class="admin-topo"><div><h1>Moderação de denúncias</h1><p>Fila de conteúdos denunciados aguardando revisão.</p></div></div><?php if(isset($_GET['ok'])): ?><p class="alerta-sucesso">Revisão registrada.</p><?php endif; ?><?php if(!$items): ?><div class="empty-moderation">Não há denúncias pendentes.</div><?php else: foreach($items as $item): ?><article class="moderation-card"><div class="moderation-meta"><strong><?=htmlspecialchars($labels[$item['content_type']]??$item['content_type'])?></strong><span>ID #<?= (int)$item['content_id'] ?></span><span>Denunciante: <?=htmlspecialchars($item['reporter'])?></span><span><?=htmlspecialchars($item['created_at'])?></span></div><h3><?=htmlspecialchars($item['reason'])?></h3><div class="moderation-details"><?=htmlspecialchars($item['details'])?></div><div class="moderation-actions"><?php foreach(['kept'=>'Manter','hidden'=>'Ocultar','removed'=>'Remover'] as $status=>$label): ?><form method="post"><input type="hidden" name="csrf_token" value="<?=htmlspecialchars(csrf_token())?>"><input type="hidden" name="content_type" value="<?=htmlspecialchars($item['content_type'])?>"><input type="hidden" name="content_id" value="<?= (int)$item['content_id'] ?>"><input type="hidden" name="status" value="<?=$status?>"><button class="<?=$status==='kept'?'keep':($status==='hidden'?'hide':'remove')?>" type="submit"><?=$label?></button></form><?php endforeach; ?></div></article><?php endforeach; endif; ?></main><script src="../JS/acessibilidade.js" defer></script><script src="../JS/liquid-glass.js?v=99" defer></script></body></html>
